// Drive headless Chrome over CDP (no puppeteer) to verify the batch-save
// in-flight locking behavior on the real page.
const fs = require("fs");
const http = require("http");

const PORT = Number(fs.readFileSync("/tmp/cbtest/port", "utf8").trim());
const BASE = `http://127.0.0.1:${PORT}`;

function getJson(path) {
  return new Promise((resolve, reject) => {
    http.get(BASE + path, res => {
      let data = "";
      res.on("data", c => (data += c));
      res.on("end", () => resolve(JSON.parse(data))));
    }).on("error", reject);
  });
}

function cdpList(debugPort) {
  return new Promise((resolve, reject) => {
    http.get(`http://127.0.0.1:${debugPort}/json/list`, res => {
      let data = "";
      res.on("data", c => (data += c));
      res.on("end", () => resolve(JSON.parse(data)));
    }).on("error", reject);
  });
}

let failures = 0;
function check(label, cond, detail) {
  console.log((cond ? "PASS " : "FAIL ") + label + (detail !== undefined ? "  " + JSON.stringify(detail) : ""));
  if (!cond) failures++;
}

async function main() {
  const { spawn } = require("child_process");
  const profileDir = "/tmp/cbtest/chrome-profile";
  fs.rmSync(profileDir, { recursive: true, force: true });
  fs.mkdirSync(profileDir, { recursive: true });
  const chrome = spawn("/usr/bin/google-chrome", [
    "--headless=new", "--no-sandbox", "--disable-gpu",
    "--remote-debugging-port=0",
    `--user-data-dir=${profileDir}`,
    "about:blank",
  ], { stdio: ["ignore", "ignore", "inherit"] });

  // Wait for DevToolsActivePort file.
  let debugPort = 0;
  for (let i = 0; i < 100; i++) {
    try {
      const f = fs.readFileSync(profileDir + "/DevToolsActivePort", "utf8").trim().split("\n");
      debugPort = Number(f[0]);
      break;
    } catch {
      await new Promise(r => setTimeout(r, 100));
    }
  }
  if (!debugPort) throw new Error("chrome devtools port not found");

  const targets = await cdpList(debugPort);
  const page = targets.find(t => t.type === "page");
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

  let nextId = 1;
  const pendings = new Map();
  ws.onmessage = ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pendings.has(msg.id)) {
      const { resolve, reject, method } = pendings.get(msg.id);
      pendings.delete(msg.id);
      if (msg.error) reject(new Error(method + ": " + JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
  };
  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pendings.set(id, { resolve, reject, method });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async function evalJs(expr, awaitPromise = false) {
    const r = await send("Runtime.evaluate", {
      expression: expr, awaitPromise, returnByValue: true,
    });
    if (r.exceptionDetails) {
      throw new Error("page exception: " + JSON.stringify(r.exceptionDetails.exception
        ? r.exceptionDetails.exception.description : r.exceptionDetails.text));
    }
    return r.result.value;
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Page.navigate", { url: BASE + "/" });
  // Wait for 3 rows.
  for (;;) {
    const n = await evalJs("document.querySelectorAll('#clients-body .row-check').length");
    if (n === 3) break;
    await new Promise(r => setTimeout(r, 100));
  }

  // Install a fetch gate: batch-update requests block until __releaseBatch().
  await evalJs(`
    window.__batchCalls = 0;
    const __origFetch = window.fetch.bind(window);
    window.__origFetch = __origFetch;
    window.__holdBatch = true;
    window.fetch = function(url, opts) {
      const u = String(url);
      if (u.indexOf('/api/clients/batch-update') !== -1) {
        window.__batchCalls++;
        if (window.__holdBatch) {
          return new Promise((resolve, reject) => {
            window.__releaseBatch = function() {
              __origFetch(u, opts).then(resolve, reject);
            };
          });
        }
      }
      return __origFetch(u, opts);
    };
    true;
  `);

  const btnState = "(() => { const b = document.getElementById('batch-submit');" +
    "return {disabled: b.disabled, text: b.textContent," +
    "busy: !!document.querySelector('#batch-report .banner.busy')};})()";

  // ---- Scenario 1: submit 甲+乙 with source=展会, then interact while pending ----
  await evalJs(`
    (() => {
      const click = el => el.dispatchEvent(new MouseEvent('click', {bubbles: true}));
      const setCheck = (id, on) => {
        const box = document.querySelector('.row-check[value="'+id+'"]');
        if (box.checked !== on) { box.checked = on; box.dispatchEvent(new Event('change', {bubbles: true})); }
      };
      setCheck(1, true);
      setCheck(2, true);
      document.querySelector('input[name="source-op"][value="set"]').click();
      document.querySelector('#batch-fields .bf[data-field="source"] .bf-value').value = '展会';
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  let st = await evalJs(btnState);
  check("点击保存后立即禁用并显示正在保存", st.disabled && st.text === "正在保存…" && st.busy, st);

  // 逐条勾选丙（最初未选中）
  await evalJs(`
    (() => {
      const box = document.querySelector('.row-check[value="3"]');
      box.checked = true;
      box.dispatchEvent(new Event('change', {bubbles: true}));
    })();
  `);
  st = await evalJs(btnState);
  check("等待中勾选丙不恢复按钮", st.disabled && st.text === "正在保存…" && st.busy, st);

  // 全选 / 取消全选
  await evalJs(`document.getElementById('check-all').click();`);
  st = await evalJs(btnState);
  check("等待中点全选不恢复按钮", st.disabled && st.text === "正在保存…", st);
  await evalJs(`document.getElementById('check-all').click();`);
  st = await evalJs(btnState);
  check("等待中点取消全选不恢复按钮", st.disabled && st.text === "正在保存…", st);

  // 重新勾选甲，再从已选客户展示中移除
  await evalJs(`
    (() => {
      const box = document.querySelector('.row-check[value="1"]');
      box.checked = true;
      box.dispatchEvent(new Event('change', {bubbles: true}));
      document.querySelector('#sel-list [data-remove="1"]').click();
    })();
  `);
  st = await evalJs(btnState);
  check("等待中移除已选客户不恢复按钮", st.disabled && st.text === "正在保存…", st);

  // 表单再次触发提交（如回车）
  await evalJs(`document.getElementById('batch-form').requestSubmit();`);
  st = await evalJs(btnState);
  check("等待中再次提交维持等待状态", st.disabled && st.text === "正在保存…" && st.busy, st);

  const callsBefore = await evalJs("window.__batchCalls");
  check("等待期间只发出了 1 次批量请求", callsBefore === 1, callsBefore);

  // 放行响应，等待整次结果处理结束
  const report1 = await evalJs(`
    (async () => {
      window.__releaseBatch();
      await new Promise(resolve => {
        const t = setInterval(() => {
          if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
            clearInterval(t); resolve();
          }
        }, 30);
      });
      return document.getElementById('batch-report').innerText;
    })();
  `, true);
  check("成功后显示去重处理数量 2", /已成功处理\s*2\s*名客户/.test(report1), report1);

  st = await evalJs(btnState);
  check("成功清除勾选后按钮重新不可提交", st.disabled && st.text === "保存修改", st);
  const callsAfter = await evalJs("window.__batchCalls");
  check("整轮只有 1 次批量请求（丙未被补交）", callsAfter === 1, callsAfter);

  // 丙不应受影响；甲乙来源应为“展会”；勾选与表单已复位
  const clients1 = (await getJson("/api/clients")).clients;
  const byId = Object.fromEntries(clients1.map(c => [c.id, c]));
  check("甲来源已改为展会", byId[1].source === "展会", byId[1]);
  check("乙来源已改为展会", byId[2].source === "展会", byId[2]);
  check("未在本次提交中的丙完全不变", byId[3].source === null, byId[3]);
  const pageAfter = await evalJs(`
    (() => ({
      checked: [...document.querySelectorAll('.row-check')].filter(b => b.checked).length,
      selCount: document.getElementById('sel-count').textContent,
      keepChecked: [...document.querySelectorAll('input[type=radio"]')]
        .filter(r => r.value === 'keep').every(r => r.checked),
      value: document.querySelector('#batch-fields .bf[data-field="source"] .bf-value').value,
      valueDisabled: document.querySelector('#batch-fields .bf[data-field="source"] .bf-value').disabled,
    }))();
  `);
  check("成功后勾选已清除、字段恢复保持原值",
    pageAfter.checked === 0 && pageAfter.selCount === "0" &&
    pageAfter.keepChecked && pageAfter.value === "" && pageAfter.valueDisabled, pageAfter);

  // ---- Scenario 2: 服务明确拒绝（坏日期）→ 保留勾选与填写，可修正后再保存 ----
  await evalJs(`
    (() => {
      const box = document.querySelector('.row-check[value="1"]');
      box.checked = true;
      box.dispatchEvent(new Event('change', {bubbles: true}));
      document.querySelector('input[name="important_date-op"][value="set"]').click();
      document.querySelector('#batch-fields .bf[data-field="important_date"] .bf-value').value = '2023-02-29';
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  const rejectReport = await evalJs(`
    new Promise(resolve => {
      const t = setInterval(() => {
        if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
          clearInterval(t);
          resolve(document.getElementById('batch-report').innerText);
        }
      }, 30);
    });
  `, true);
  check("拒绝时显示具体原因", /全部拒绝/.test(rejectReport) && /2023-02-29/.test(rejectReport) && /日历/.test(rejectReport),
    rejectReport);
  const afterReject = await evalJs(`
    (() => {
      const b = document.getElementById('batch-submit');
      return {
        enabled: !b.disabled && b.textContent === '保存修改',
        checked: document.querySelector('.row-check[value="1"]').checked,
        radioSet: document.querySelector('input[name="important_date-op"][value="set"]').checked,
        value: document.querySelector('#batch-fields .bf[data-field="important_date"] .bf-value').value,
      };
    })();
  `);
  check("拒绝后等待结束、按钮可用", afterReject.enabled, afterReject);
  check("拒绝后保留勾选与字段操作及填写内容",
    afterReject.checked && afterReject.radioSet && afterReject.value === "2023-02-29", afterReject);

  // 修正日期后主动再保存 → 成功
  await evalJs(`
    (() => {
      document.querySelector('#batch-fields .bf[data-field="important_date"] .bf-value').value = '2024-02-29';
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  await evalJs(`
    new Promise(resolve => {
      const t = setInterval(() => {
        if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
          clearInterval(t); resolve();
        }
      }, 30);
    });
  `, true);
  const clients2 = (await getJson("/api/clients")).clients;
  const c1 = clients2.find(c => c.id === 1);
  check("修正后主动再保存生效（来源仍是展会，日期更新）",
    c1.source === "展会" && c1.important_date === "2024-02-29", c1);
  const c3 = clients2.find(c => c.id === 3);
  check("丙始终未受任何提交影响", c3.source === null && c3.important_date === null, c3);

  // ---- Scenario 3: 请求失败 → 结束等待、显示失败、页面可继续使用 ----
  await evalJs(`
    (() => {
      window.fetch = function() {
        if (String(arguments[0]).indexOf('/api/clients/batch-update') !== -1) {
          return Promise.reject(new Error('网络中断（模拟）'));
        }
        return window.__origFetch.apply(window, arguments);
      };
      const box = document.querySelector('.row-check[value="2"]');
      box.checked = true;
      box.dispatchEvent(new Event('change', {bubbles: true}));
      document.querySelector('input[name="industry-op"][value="clear"]').click();
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  const failReport = await evalJs(`
    new Promise(resolve => {
      const t = setInterval(() => {
        if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
          clearInterval(t);
          resolve(document.getElementById('batch-report').innerText);
        }
      }, 30);
    });
  `, true);
  check("请求失败显示失败信息", /请求失败/.test(failReport) && /网络中断/.test(failReport), failReport);
  const afterFail = await evalJs(`
    (() => { const b = document.getElementById('batch-submit');
      return {enabled: !b.disabled, text: b.textContent,
        checked: document.querySelector('.row-check[value="2"]').checked}; })();
  `);
  check("失败后等待结束、页面可继续使用",
    afterFail.enabled && afterFail.text === "保存修改" && afterFail.checked, afterFail);

  // 恢复网络后主动再保存成功，且不会自动补交失败期间的操作
  await evalJs(`
    (() => {
      window.fetch = window.__origFetch;
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  await evalJs(`
    new Promise(resolve => {
      const t = setInterval(() => {
        if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
          clearInterval(t); resolve();
        }
      }, 30);
    });
  `, true);
  const clients3 = (await getJson("/api/clients")).clients;
  const c2 = clients3.find(c => c.id === 2);
  check("恢复后由用户重新主动提交才生效", c2.industry === null, c2);

  ws.close();
  chrome.kill();
  console.log("\n" + (failures === 0 ? "全部通过" : failures + " 项失败"));
  process.exit(failures ? 1 : 0);
}

main().catch(err => { console.error(err); process.exit(2); });

