  // 全选 / 取消全选
  await evalJs(`document.getElementById('check-all').click();`);
  st = await evalJs(btnState);
  check("等待中点全选不恢复按钮", st.disabled && st.text === "正在保存…", st);
  await evalJs(`document.getElementById('check-all').click();`);
  st = await evalJs(btnState);
  check("等待中点取消全选不恢复按钮", st.disabled && st.text === "正在保存…", st);

  // 重新勾选甲，再从已选客户展示中移除
  await evalJs(`
    (() => {
      const box = document.querySelector('.row-check[value="1"]');
      box.checked = true;
      box.dispatchEvent(new Event('change', {bubbles: true}));
      document.querySelector('#sel-list [data-remove="1"]').click();
    })();
  `);
  st = await evalJs(btnState);
  check("等待中移除已选客户不恢复按钮", st.disabled && st.text === "正在保存…", st);

  // 表单再次触发提交（如回车）
  await evalJs(`document.getElementById('batch-form').requestSubmit();`);
  st = await evalJs(btnState);
  check("等待中再次提交维持等待状态", st.disabled && st.text === "正在保存…" && st.busy, st);

  const callsBefore = await evalJs("window.__batchCalls");
  check("等待期间只发出了 1 次批量请求", callsBefore === 1, callsBefore);

  // 放行响应，等待整次结果处理结束
  const report1 = await evalJs(`
    (async () => {
      window.__releaseBatch();
      await new Promise(resolve => {
        const t = setInterval(() => {
          if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
            clearInterval(t); resolve();
          }
        }, 30);
      });
      return document.getElementById('batch-report').innerText;
    })();
  `, true);
  check("成功后显示去重处理数量 2", /已成功处理\s*2\s*名客户/.test(report1), report1);

  st = await evalJs(btnState);
  check("成功清除勾选后按钮重新不可提交", st.disabled && st.text === "保存修改", st);
  const callsAfter = await evalJs("window.__batchCalls");
  check("整轮只有 1 次批量请求（丙未被补交）", callsAfter === 1, callsAfter);

  // 丙不应受影响；甲乙来源应为“展会”；勾选与表单已复位
  const clients1 = (await getJson("/api/clients")).clients;
  const byId = Object.fromEntries(clients1.map(c => [c.id, c]));
  check("甲来源已改为展会", byId[1].source === "展会", byId[1]);
  check("乙来源已改为展会", byId[2].source === "展会", byId[2]);
  check("未在本次提交中的丙完全不变", byId[3].source === null, byId[3]);
  const pageAfter = await evalJs(`
    (() => ({
      checked: [...document.querySelectorAll('.row-check')].filter(b => b.checked).length,
      selCount: document.getElementById('sel-count').textContent,
      keepChecked: [...document.querySelectorAll('input[type=radio"]')]
        .filter(r => r.value === 'keep').every(r => r.checked),
      value: document.querySelector('#batch-fields .bf[data-field="source"] .bf-value').value,
      valueDisabled: document.querySelector('#batch-fields .bf[data-field="source"] .bf-value').disabled,
    }))();
  `);
  check("成功后勾选已清除、字段恢复保持原值",
    pageAfter.checked === 0 && pageAfter.selCount === "0" &&
    pageAfter.keepChecked && pageAfter.value === "" && pageAfter.valueDisabled, pageAfter);

  // ---- Scenario 2: 服务明确拒绝（坏日期）→ 保留勾选与填写，可修正后再保存 ----
  await evalJs(`
    (() => {
      const box = document.querySelector('.row-check[value="1"]');
      box.checked = true;
      box.dispatchEvent(new Event('change', {bubbles: true}));
      document.querySelector('input[name="important_date-op"][value="set"]').click();
      document.querySelector('#batch-fields .bf[data-field="important_date"] .bf-value').value = '2023-02-29';
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  const rejectReport = await evalJs(`
    new Promise(resolve => {
      const t = setInterval(() => {
        if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
          clearInterval(t);
          resolve(document.getElementById('batch-report').innerText);
        }
      }, 30);
    });
  `, true);
  check("拒绝时显示具体原因", /全部拒绝/.test(rejectReport) && /2023-02-29/.test(rejectReport) && /日历/.test(rejectReport),
    rejectReport);
  const afterReject = await evalJs(`
    (() => {
      const b = document.getElementById('batch-submit');
      return {
        enabled: !b.disabled && b.textContent === '保存修改',
        checked: document.querySelector('.row-check[value="1"]').checked,
        radioSet: document.querySelector('input[name="important_date-op"][value="set"]').checked,
        value: document.querySelector('#batch-fields .bf[data-field="important_date"] .bf-value').value,
      };
    })();
  `);
  check("拒绝后等待结束、按钮可用", afterReject.enabled, afterReject);
  check("拒绝后保留勾选与字段操作及填写内容",
    afterReject.checked && afterReject.radioSet && afterReject.value === "2023-02-29", afterReject);

  // 修正日期后主动再保存 → 成功
  await evalJs(`
    (() => {
      document.querySelector('#batch-fields .bf[data-field="important_date"] .bf-value').value = '2024-02-29';
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  await evalJs(`
    new Promise(resolve => {
      const t = setInterval(() => {
        if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
          clearInterval(t); resolve();
        }
      }, 30);
    });
  `, true);
  const clients2 = (await getJson("/api/clients")).clients;
  const c1 = clients2.find(c => c.id === 1);
  check("修正后主动再保存生效（来源仍是展会，日期更新）",
    c1.source === "展会" && c1.important_date === "2024-02-29", c1);
  const c3 = clients2.find(c => c.id === 3);
  check("丙始终未受任何提交影响", c3.source === null && c3.important_date === null, c3);

  // ---- Scenario 3: 请求失败 → 结束等待、显示失败、页面可继续使用 ----
  await evalJs(`
    (() => {
      window.fetch = function() {
        if (String(arguments[0]).indexOf('/api/clients/batch-update') !== -1) {
          return Promise.reject(new Error('网络中断（模拟）'));
        }
        return window.__origFetch.apply(window, arguments);
      };
      const box = document.querySelector('.row-check[value="2"]');
      box.checked = true;
      box.dispatchEvent(new Event('change', {bubbles: true}));
      document.querySelector('input[name="industry-op"][value="clear"]').click();
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
  const failReport = await evalJs(`
    new Promise(resolve => {
      const t = setInterval(() => {
        if (document.getElementById('batch-submit').textContent.indexOf('正在保存') === -1) {
          clearInterval(t);
          resolve(document.getElementById('batch-report').innerText);
        }
      }, 30);
    });
  `, true);
  check("请求失败显示失败信息", /请求失败/.test(failReport) && /网络中断/.test(failReport), failReport);
  const afterFail = await evalJs(`
    (() => { const b = document.getElementById('batch-submit');
      return {enabled: !b.disabled, text: b.textContent,
        checked: document.querySelector('.row-check[value="2"]').checked}; })();
  `);
  check("失败后等待结束、页面可继续使用",
    afterFail.enabled && afterFail.text === "保存修改" && afterFail.checked, afterFail);

  // 恢复网络后主动再保存成功，且不会自动补交失败期间的操作
  await evalJs(`
    (() => {
      window.fetch = window.__origFetch;
      document.getElementById('batch-form').requestSubmit();
    })();
  `);
